﻿// src/ui/mapped-folder-bind.ts
// Bind Choose Folder button + Scripts <select> to mapped-folder SSOT.
// Safe no-op if elements are missing.

import { getMappedFolder, initMappedFolder, listScripts, onMappedFolder, pickMappedFolder } from '../fs/mapped-folder';
import {
  getMappedFolderManagerHint,
  isMappedFolderManagedByNursery,
} from '../fs/mapped-folder';
import { ScriptStore } from '../features/scripts-store';
import { debugLog, hudLog } from '../env/logging';
import { getNurseryStorageSettingsUrl } from '../forge/nursery-mounts';
import {
  listRecordingSessionsForWorkspace,
  listWorkspaceReadyScripts,
  readRecordingSessionScripts,
  type RecordingSessionSummary,
} from '../forge/ready-scripts';
import {
  getScriptSourceMode,
  getSelectedRecordingSessionId,
  setScriptSourceMode,
  setSelectedRecordingSessionId,
  type ScriptSourceMode,
} from '../forge/script-source';
import {
  consumeLastScriptId,
  loadScriptById,
  persistLastScriptId,
  restoreStillPossible,
} from '../features/script-selection';
import { setCurrentScriptHandle } from '../fs/script-doc';
import { scriptBaseName } from '../fs/script-naming';

function getFolderPickerEnvironmentHint(): string {
  try {
    const proto = window.location.protocol;
    const ua = navigator.userAgent || '';

    if (proto === 'file:') {
      return 'Folder picking is blocked when running from file://. Please run Anvil on http://localhost or https:// instead.';
    }

    const hasFS = typeof (window as any).showDirectoryPicker === 'function';
    const hasWebkitDir = (() => {
      const i = document.createElement('input');
      return 'webkitdirectory' in i || 'directory' in i;
    })();

    if (!hasFS && !hasWebkitDir) {
      return 'This browser/webview does not support folder picking. Use Chrome or Edge on http://localhost or https://.';
    }

    if (/OBS|Electron|WebView|Headless/i.test(ua)) {
      return 'This embedded browser may not allow folder picking. Choose a scripts folder in a full browser (Chrome/Edge) first, then reopen Anvil here.';
    }
  } catch {
    // ignore
  }

  return 'Folder picking is not available in this environment. Try running Anvil in a full browser (Chrome/Edge on http://localhost or https://).';
}

const SUPPORTED_EXT = /\.(docx|doc|txt|md)$/i;
const shouldTraceMappedFolder = (() => {
  let cache: boolean | null = null;
  return () => {
    if (cache !== null) return cache;
    try {
      const w = window as any;
      cache = !!(w.__TP_DEV || w.__TP_DEV1 || /dev=1/.test(location.search || ''));
    } catch {
      cache = false;
    }
    return cache;
  };
})();

const OPEN_NURSERY_STORAGE_COMMAND = '__OPEN_NURSERY_STORAGE__';

function openNurseryStorageSettings() {
  const url = getNurseryStorageSettingsUrl();
  try {
    window.location.assign(url);
  } catch {}
}
let restoredLastScript = false;
const fingerprintNames = (entries: { name: string }[]) =>
  entries
    .map((e) => String(e?.name || ''))
    .sort()
    .join('|');
const lastPopulateFingerprints = new WeakMap<HTMLSelectElement, string>();
const lastFallbackFingerprints = new WeakMap<HTMLSelectElement, string>();
function isSupportedScriptName(name: string): boolean {
  const lower = (name || '').toLowerCase().trim();
  if (!lower) return false;
  if (lower.startsWith('~$')) return false; // temp Office files
  if (lower.startsWith('.')) return false;  // hidden/system
  if (lower === 'thumbs.db') return false;
  if (SUPPORTED_EXT.test(lower)) return true;
  // Allow extensionless names (treat as plain text scripts)
  if (!lower.includes('.')) return true;
  const lastDot = lower.lastIndexOf('.');
  if (lastDot === 0) return false;
  return false;
}

type BindOpts = {
  button: string | HTMLElement; // Choose Folder button selector or element
  select: string | HTMLSelectElement; // Scripts dropdown selector or element
  fallbackInput?: string | HTMLInputElement; // optional <input type="file" webkitdirectory>
  onSelect?: (_fileOrHandle: FileSystemFileHandle | File | null) => void; // callback when user picks a script
};

export async function handleChooseFolder(doc: Document = document): Promise<void> {
  const handleInitFailure = (err: any) => {
    try {
      console.warn('[mapped-folder] initMappedFolder failed', err);
    } catch {}
    try {
      const toastFn = (window as any).toast;
      if (typeof toastFn === 'function') {
        toastFn('Could not initialize mapped folder. Check console for details.');
      }
    } catch {}
  };

  const initGuard = initMappedFolder().catch((err) => {
    handleInitFailure(err);
    throw err;
  });
  const awaitInit = async () => {
    try {
      await initGuard;
      return true;
    } catch {
      return false;
    }
  };

  const initOk = await awaitInit();
  if (!initOk) return;

  if (isMappedFolderManagedByNursery()) {
    const settingsUrl = getNurseryStorageSettingsUrl();
    const toastFn = (window as any).toast;
    if (typeof toastFn === 'function') {
      toastFn(`Scripts folder is managed by The Forge. Configure it in The Forge > Settings > Storage (${settingsUrl}).`, {
        type: 'warn',
      });
    }
    return;
  }

  const hasFS = typeof (window as any).showDirectoryPicker === 'function';
  const fallback = doc.getElementById('folderFallback') as HTMLInputElement | null;
  let picked = false;

  if (hasFS) {
    try {
      await pickMappedFolder();
      picked = true;
    } catch (err) {
      try { console.info('[mapped-folder] directory picker cancelled/failed, falling back', err); } catch {}
    }
  }

  if (!picked && fallback) {
    try {
      fallback.click();
      picked = true;
    } catch (err) {
      try { console.warn('[mapped-folder] folderFallback click failed', err); } catch {}
    }
  }

  if (picked) {
    return;
  }

  try {
    const toastFn = (window as any).toast;
    if (typeof toastFn === 'function') {
      toastFn(getFolderPickerEnvironmentHint());
    }
  } catch {}

  try {
    console.warn('[mapped-folder] no supported folder picker available (both FS API and fallback failed)');
  } catch {}
}

export async function bindMappedFolderUI(opts: BindOpts): Promise<() => void> {
  const btn = typeof opts.button === 'string' ? document.querySelector(opts.button) as HTMLButtonElement : opts.button as HTMLButtonElement;
  const sel = typeof opts.select === 'string' ? document.querySelector(opts.select) as HTMLSelectElement : opts.select as HTMLSelectElement;
  const fallback = opts.fallbackInput ? (typeof opts.fallbackInput === 'string' ? document.querySelector(opts.fallbackInput) as HTMLInputElement : opts.fallbackInput) : null;
  const sidebar = document.getElementById('scriptSelectSidebar') as HTMLSelectElement | null;
  const sourceSelect = document.getElementById('scriptSourceSelect') as HTMLSelectElement | null;
  const recordingSessionRow = document.getElementById('recordingSessionRow') as HTMLElement | null;
  const recordingSessionSelect = document.getElementById('recordingSessionSelect') as HTMLSelectElement | null;
  const sourceStatus = document.getElementById('scriptSourceStatus') as HTMLElement | null;
  const sourceIndicator = document.getElementById('scriptSourceIndicator') as HTMLElement | null;

  if (!btn || !sel) return () => {};
  // Avoid double-binding across reinjections
  if ((btn as any).dataset && (btn as any).dataset.mappedFolderWired === '1') {
    return () => {};
  }

  // Reassurance hint: folder picker may look empty; mapping still works and files are filtered after selection.
  try {
    const hintId = `${sel.id || 'scripts'}-picker-hint`;
    let hint = document.getElementById(hintId) as HTMLElement | null;
    if (!hint) {
      hint = document.createElement('p');
      hint.id = hintId;
      hint.className = 'sidebar-hint';
      hint.textContent = 'Note: The folder picker may look empty. Choose the folder; Anvil will scan supported script files automatically.';
      if (sel.parentElement) {
        sel.parentElement.appendChild(hint);
      }
    }
  } catch {}

  let didInit = false;
  const ensureInit = async () => {
    if (didInit) return;
    didInit = true;
    await initMappedFolder();
  };
  const defaultChooseLabel = (btn.textContent || 'Choose Folder').trim() || 'Choose Folder';
  const updateSourceIndicator = (mode: ScriptSourceMode, sessionTitle?: string | null, scriptCount?: number) => {
    const countLabel = typeof scriptCount === 'number'
      ? `${scriptCount} script${scriptCount === 1 ? '' : 's'}`
      : null;
    const indicatorText = mode === 'session'
      ? (
        sessionTitle
          ? `Source: Session - ${sessionTitle}${countLabel ? ` (${countLabel})` : ''}`
          : 'Source: Session - not selected'
      )
      : 'Source: Library';
    if (sourceIndicator) {
      sourceIndicator.textContent = indicatorText;
    }
    if (sourceStatus) {
      sourceStatus.textContent = mode === 'session'
        ? (
          sessionTitle
            ? (
              countLabel
                ? `Session mode active. ${countLabel} loaded from "${sessionTitle}".`
                : `Session mode active. Scripts are loaded from "${sessionTitle}".`
            )
            : 'Session mode active. Select a recording session to load scripts.'
        )
        : 'Library mode active. Scripts are loaded from Workspace Library.';
    }
  };

  const loadSessionOptions = async (preferredId?: string | null): Promise<RecordingSessionSummary[]> => {
    if (!recordingSessionSelect) return [];
    let sessions: RecordingSessionSummary[] = [];
    try {
      sessions = await listRecordingSessionsForWorkspace();
    } catch {
      sessions = [];
    }

    recordingSessionSelect.innerHTML = '';
    if (!sessions.length) {
      recordingSessionSelect.disabled = true;
      recordingSessionSelect.append(new Option('No recording sessions', '', true, true));
      setSelectedRecordingSessionId(null);
      updateSourceIndicator('session', null);
      return [];
    }

    recordingSessionSelect.disabled = false;
    for (const session of sessions) {
      recordingSessionSelect.append(new Option(session.title, session.id));
    }

    const storedId = getSelectedRecordingSessionId();
    const targetId = preferredId ?? storedId;
    const chosen = targetId && sessions.some((session) => session.id === targetId)
      ? targetId
      : sessions[0].id;
    recordingSessionSelect.value = chosen;
    setSelectedRecordingSessionId(chosen);
    const selected = sessions.find((session) => session.id === chosen) ?? null;
    updateSourceIndicator('session', selected?.title ?? null);
    return sessions;
  };

  const applySourceUi = () => {
    const mode = getScriptSourceMode();
    if (sourceSelect) sourceSelect.value = mode;
    if (recordingSessionRow) recordingSessionRow.hidden = mode !== 'session';
    if (mode === 'library') {
      updateSourceIndicator('library', null, 0);
    }
  };

  const ensureManagementUi = () => {
    const managed = isMappedFolderManagedByNursery();
    const managedHint = getMappedFolderManagerHint();
    const recheckBtn = document.getElementById('recheckFolderBtn') as HTMLButtonElement | null;
    const settingsUrl = getNurseryStorageSettingsUrl();

    if (managed) {
      btn.disabled = true;
      btn.textContent = 'Managed by The Forge';
      btn.title = `Set scripts folder in The Forge Storage (${settingsUrl}).`;
      if (fallback) fallback.disabled = true;
      if (recheckBtn) {
        recheckBtn.disabled = true;
        recheckBtn.title = `Managed by The Forge Storage (${settingsUrl}).`;
      }
    } else {
      btn.disabled = false;
      btn.textContent = defaultChooseLabel;
      btn.title = '';
      if (fallback) fallback.disabled = false;
      if (recheckBtn) {
        recheckBtn.disabled = false;
        recheckBtn.title = '';
      }
    }

    const card = document.getElementById('scriptsFolderCard');
    if (!card) return;
    let note = card.querySelector<HTMLElement>('[data-managed-by="nursery"]');
    if (!note) {
      note = document.createElement('div');
      note.className = 'settings-small';
      note.dataset.managedBy = 'nursery';
      note.style.marginTop = '6px';
      card.appendChild(note);
    }
    note.textContent = managed
      ? `Managed by The Forge Storage${managedHint ? ` (${managedHint})` : ''}.`
      : '';
  };

  try { (btn as any).dataset.mappedFolderWired = '1'; } catch {}
  applySourceUi();
  btn.addEventListener('click', (ev) => {
    try { ev.preventDefault(); } catch {}
    void handleChooseFolder(document);
  });

  if (fallback) {
    fallback.addEventListener('change', () => {
      try {
        const files = Array.from(fallback.files || []);
        // If user canceled or automation triggered empty selection, ignore silently
        if (!files.length) { hudLog('folder:fallback:empty'); return; }
        populateSelectFromFiles(files);
      } catch {}
    });
  }

  if (sourceSelect) {
    sourceSelect.value = getScriptSourceMode();
    sourceSelect.addEventListener('change', () => {
      const nextMode: ScriptSourceMode = sourceSelect.value === 'library' ? 'library' : 'session';
      setScriptSourceMode(nextMode);
      applySourceUi();
      if (nextMode === 'session') {
        void loadSessionOptions().then(() => {
          void refreshList();
        });
        return;
      }
      setSelectedRecordingSessionId(null);
      if (recordingSessionSelect) {
        recordingSessionSelect.value = '';
      }
      try { ScriptStore.syncReady([]); } catch {}
      updateSourceIndicator('library', null, 0);
      void refreshList();
    });
  }

  if (recordingSessionSelect) {
    recordingSessionSelect.addEventListener('change', () => {
      const nextId = (recordingSessionSelect.value || '').trim();
      setSelectedRecordingSessionId(nextId || null);
      void refreshList();
    });
  }

  sel.addEventListener('change', async () => {
    debugLog('[MAPPED-FOLDER] change', { id: sel.id, value: sel.value });
    try {
      const opt = sel.selectedOptions && sel.selectedOptions[0] ? sel.selectedOptions[0] : sel.options[sel.selectedIndex];
      if (!opt) return;
      sel.setAttribute('aria-busy','true');
      const scriptId = opt.value || '';
      if ((opt as any)?.dataset?.nurseryLink === '1' || scriptId === OPEN_NURSERY_STORAGE_COMMAND) {
        openNurseryStorageSettings();
        return;
      }
      if ((opt as any)?.dataset?.settingsLink === '1') {
        try { document.getElementById('settingsBtn')?.click(); } catch {}
        try { requestAnimationFrame(() => { try { document.getElementById('scriptsFolderCard')?.scrollIntoView({ block: 'start', behavior: 'smooth' }); } catch {} }); } catch {}
        return;
      }
      let loaded = false;
      if (scriptId) {
        persistLastScriptId(scriptId);
        loaded = await loadScriptById(scriptId);
        if (loaded) {
          syncSidebarSelection(scriptId);
          return;
        }
      }
      const handle = (opt as any)?.__handle || (opt as any)?._handle;
      const file = (opt as any)?.__file || (opt as any)?._file;
      const ensureReadPermission = async (h: any): Promise<boolean> => {
        try {
          const hasQuery = typeof h?.queryPermission === 'function';
          const hasRequest = typeof h?.requestPermission === 'function';
          if (!hasQuery && !hasRequest) return true;
          const q = hasQuery ? await h.queryPermission({ mode: 'read' }) : undefined;
          if (q === 'granted') return true;
          if (!hasRequest) return true;
          const r = await h.requestPermission({ mode: 'read' });
          return r === 'granted';
        } catch { return true; }
      };
      if (handle && !(await ensureReadPermission(handle))) {
        try { hudLog('folder:permission:denied', { id: sel.id }); } catch {}
        toast(
          isMappedFolderManagedByNursery()
            ? `Allow folder access, then re-link scripts mount in The Forge Storage (${getNurseryStorageSettingsUrl()}).`
            : 'Allow folder access to load scripts, or re-pick the folder in Settings.',
        );
        return;
      }
      if (handle || file) {
        const { name, text } = await readHandleOrFile(handle || file);
        try { (window as any).__tpCurrentName = name; } catch {}
        try { localStorage.setItem('tp_last_script_name', name); } catch {}
        try {
          const folder = getMappedFolder();
          setCurrentScriptHandle(handle || null, folder, name);
          const titleInput = document.getElementById('scriptTitle') as HTMLInputElement | null;
          if (titleInput) {
            titleInput.value = scriptBaseName(name);
          }
        } catch {}
        window.dispatchEvent(new CustomEvent('tp:script-load', { detail: { name, text } }));
        if (scriptId) {
          persistLastScriptId(scriptId);
          syncSidebarSelection(scriptId);
        }
      } else {
        opts.onSelect?.(null);
        // In CI mock mode, emit a synthetic apply so smoke can assert content updates
        const mockMode = !!(window as any).__tpMockFolderMode;
        if (mockMode) {
          const name = opt?.text || 'Mock_Script.txt';
          const text = `This is a CI mock script for ${name}.\n\n- Line 1\n- Line 2\n- Line 3`;
          hudLog('script:loaded:mock', { name, chars: text.length });
          try { localStorage.setItem('tp_last_script_name', name); } catch {}
          try { window.dispatchEvent(new CustomEvent('tp:script-load', { detail: { name, text } })); } catch {}
          if (scriptId) {
            persistLastScriptId(scriptId);
            syncSidebarSelection(scriptId);
          }
        }
        // Settings link sentinel (sidebar placeholder when no folder mapped)
        if ((opt as any).dataset && (opt as any).dataset.settingsLink === '1') {
          try { document.getElementById('settingsBtn')?.click(); } catch {}
          try { requestAnimationFrame(() => { try { document.getElementById('scriptsFolderCard')?.scrollIntoView({ block: 'start', behavior: 'smooth' }); } catch {} }); } catch {}
        }
      }
    } catch (e) {
      try { console.warn('[mapped-folder] load failed', e); } catch {}
      try { hudLog('folder:load:error', { id: sel.id, err: (e as any)?.name || (e as any)?.message || String(e) }); } catch {}
      try {
        toast(
          isMappedFolderManagedByNursery()
            ? `Could not load script from The Forge-managed folder. Recheck The Forge Storage link (${getNurseryStorageSettingsUrl()}).`
            : 'Could not load script from the mapped folder. Recheck permissions or pick the folder again.',
        );
      } catch {}
    }
    finally { try { sel.setAttribute('aria-busy','false'); } catch {} }
  });

  const off = onMappedFolder(async () => { await refreshList(); });
  const onRefresh: EventListener = () => { try { refreshList(); } catch {}; };
  const onScriptSourceChanged: EventListener = () => {
    applySourceUi();
    void refreshList();
  };
  const onRecordingSessionChanged: EventListener = () => {
    if (getScriptSourceMode() === 'session') {
      void refreshList();
    }
  };
  try { window.addEventListener('tp:folderScripts:refresh', onRefresh); } catch {}
  try { window.addEventListener('tp:script-source:changed', onScriptSourceChanged); } catch {}
  try { window.addEventListener('tp:recording-session:changed', onRecordingSessionChanged); } catch {}
  if (getScriptSourceMode() === 'session') {
    await loadSessionOptions();
  }
  await refreshList();
  return () => {
    try { off(); } catch {}
    try { window.removeEventListener('tp:folderScripts:refresh', onRefresh); } catch {}
    try { window.removeEventListener('tp:script-source:changed', onScriptSourceChanged); } catch {}
    try { window.removeEventListener('tp:recording-session:changed', onRecordingSessionChanged); } catch {}
  };

  async function refreshList() {
    try {
      ensureManagementUi();
      try { sel.setAttribute('aria-busy','true'); } catch {}

      let readyScripts = await listWorkspaceReadyScripts().catch(() => []);
      let sourceMode: ScriptSourceMode = 'library';
      let sessionTitle: string | null = null;
      const sourceUiEnabled = !!sourceSelect;
      if (sourceUiEnabled) {
        sourceMode = getScriptSourceMode();
        if (sourceMode === 'session') {
          let sessionId = getSelectedRecordingSessionId();
          if (!sessionId) {
            const sessions = await loadSessionOptions();
            sessionId = sessions[0]?.id ?? null;
          }
          if (sessionId) {
            const sessionSet = await readRecordingSessionScripts(sessionId).catch(() => null);
            readyScripts = sessionSet?.scripts ?? [];
            sessionTitle = sessionSet?.session.title ?? null;
          } else {
            readyScripts = [];
          }
          updateSourceIndicator('session', sessionTitle, readyScripts.length);
        } else {
          updateSourceIndicator('library', null, readyScripts.length);
        }
      }

      try { ScriptStore.syncReady(readyScripts); } catch {}

      // Source-driven Forge flow does not require mapped folder entries.
      const shouldUseMappedEntries = !sourceUiEnabled;
      // In deterministic CI mock mode, preserve pre-populated options (avoid wiping to "(No scripts found)")
      const mockMode = !!(window as any).__tpMockFolderMode;
      const hasPreMock = shouldUseMappedEntries && mockMode && sel && sel.options && sel.options.length > 1 && !(window as any).__tpFolder?.get?.();
      if (hasPreMock) {
        try { window.dispatchEvent(new CustomEvent('tp:folderScripts:populated', { detail: { count: sel.options.length } })); } catch {}
        return;
      }

      const entries = shouldUseMappedEntries
        ? await (async () => {
          try {
            await ensureInit();
            return await listScripts();
          } catch {
            return [];
          }
        })()
        : [];

      const entriesFingerprint = fingerprintNames(entries);
      const prevFingerprint = lastPopulateFingerprints.get(sel);
      if (!entriesFingerprint || entriesFingerprint !== prevFingerprint) {
        lastPopulateFingerprints.set(sel, entriesFingerprint);
        populateSelect(entries);
        _lastCount = entries.length;
        try { announceCount(_lastCount); } catch {}
      } else {
        try { hudLog('folder:populate:skip', { fingerprint: entriesFingerprint, count: entries.length }); } catch {}
      }
    } catch {}
    finally { try { sel.setAttribute('aria-busy','false'); } catch {} }
  }

function populateSelect(entries: { name: string; handle: FileSystemFileHandle }[]) {
  try {
    sel.innerHTML = '';
    const mappedEntries: { id: string; title: string; handle: FileSystemHandle }[] = [];
    try { sel.setAttribute('aria-busy','true'); } catch {}
      if (!entries.length) {
        const managed = isMappedFolderManagedByNursery();
        const managedHint = getMappedFolderManagerHint();
        // Sidebar gets a Settings link placeholder instead of disabled select
        if (sel.id === 'scriptSelectSidebar') {
          sel.disabled = false;
          const opt = managed
            ? new Option('Manage scripts mount in The Forge...', OPEN_NURSERY_STORAGE_COMMAND)
            : new Option('Map script folder...', '__OPEN_SETTINGS__');
          if (managed) {
            (opt as any).dataset.nurseryLink = '1';
          } else {
            (opt as any).dataset.settingsLink = '1';
          }
          sel.append(opt);
        } else {
          sel.disabled = true;
          sel.append(
            new Option(
              managed
                ? `No Forge scripts folder linked${managedHint ? ` (${managedHint})` : ''}. Configure it in The Forge Storage.`
                : 'No existing scripts yet — map folder and save new ones here',
              '',
              true,
              false,
            ),
          );
        }
        try { ScriptStore.syncMapped([]); } catch {}
        hudLog('folder:cleared', {});
        try { window.dispatchEvent(new CustomEvent('tp:folderScripts:populated', { detail: { count: 0 } })); } catch {}
        try { announceCount(0); } catch {}
        return;
    }
    sel.disabled = false;
      for (const e of entries) {
        if (shouldTraceMappedFolder()) {
          debugLog('[MAPPED-FOLDER] seen entry', {
            name: e.name,
            allowed: isSupportedScriptName(e.name),
          });
        }
        if (!isSupportedScriptName(e.name)) continue;
      const opt = new Option(e.name, e.name) as HTMLOptionElement & {
        __fileHandle?: FileSystemFileHandle;
        __file?: File;
        _handle?: FileSystemFileHandle;
        _file?: File;
      };
      try { opt._handle = e.handle; } catch {}
      try { opt.__fileHandle = e.handle; } catch {}
      try { mappedEntries.push({ id: e.name, title: e.name, handle: e.handle }); } catch {}
        if (shouldTraceMappedFolder()) {
          debugLog('[MAPPED-FOLDER] option created', {
            id: e.name,
            label: e.name,
            hasHandle: !!e.handle,
            hasFile: false,
          });
        }
        sel.append(opt);
      }
      if (shouldTraceMappedFolder()) {
        debugLog('[MAPPED-FOLDER] syncing mapped entries', {
          count: mappedEntries.length,
          sample: mappedEntries.slice(0, 3),
        });
      }
      try { ScriptStore.syncMapped(mappedEntries); } catch {}
      try { window.dispatchEvent(new CustomEvent('tp:folderScripts:populated', { detail: { count: mappedEntries.length, selectId: sel.id } })); } catch {}
      try { window.dispatchEvent(new CustomEvent('tp:scripts-updated')); } catch {}
      // Preselect last used script if present
      try {
        const restoreId = consumeLastScriptId(mappedEntries);
        if (restoreId) {
          setSelectedById(sel, restoreId);
          syncSidebarSelection(restoreId);
          restoredLastScript = true;
          hudLog('script:last:preselect', { id: restoreId });
          void loadScriptById(restoreId);
          maybeAutoLoad(sel);
        } else if (!restoreStillPossible()) {
          const last = getLastScriptName();
          if (last) {
            setSelectedByName(sel, last);
            hudLog('script:last:preselect', { name: last });
          }
          maybeAutoLoad(sel);
        }
      } catch {}
      const cnt = sel.options.length;
      try { window.dispatchEvent(new CustomEvent('tp:folderScripts:populated', { detail: { count: cnt } })); } catch {}
      try { announceCount(cnt); } catch {}
      try { sel.setAttribute('aria-busy','false'); } catch {}
      queueMicrotask(() => {
        try { if (sidebar) sidebar.value = sel.value; } catch {}
      });
    } catch {}
  }
  function populateSelectFromFiles(files: File[]) {
    try {
      const mockMode = !!(window as any).__tpMockFolderMode;
      const hasPreMock = mockMode && sel && sel.options && sel.options.length > 1 && !(window as any).__tpFolder?.get?.();
      if (hasPreMock) {
        // Preserve mock; skip replacing with fallback file list
        try { window.dispatchEvent(new CustomEvent('tp:folderScripts:populated', { detail: { count: sel.options.length } })); } catch {}
        return;
      }
      sel.innerHTML = '';
      const mappedEntries: { id: string; title: string; handle: FileSystemHandle }[] = [];
      try { sel.setAttribute('aria-busy','true'); } catch {}
      const filtered = files.filter(f => {
        if (shouldTraceMappedFolder()) {
          try {
            debugLog('[MAPPED-FOLDER] seen entry', { name: f.name, allowed: isSupportedScriptName(f.name) });
          } catch {}
        }
        return isSupportedScriptName(f.name);
      }).sort((a,b)=>a.name.localeCompare(b.name));
      if (!filtered.length) {
        const managed = isMappedFolderManagedByNursery();
        const managedHint = getMappedFolderManagerHint();
        try { ScriptStore.syncMapped([]); } catch {}
        if (sel.id === 'scriptSelectSidebar') {
          sel.disabled = false;
          const opt = managed
            ? new Option('Manage scripts mount in The Forge...', OPEN_NURSERY_STORAGE_COMMAND)
            : new Option('Map script folder...', '__OPEN_SETTINGS__');
          if (managed) {
            (opt as any).dataset.nurseryLink = '1';
          } else {
            (opt as any).dataset.settingsLink = '1';
          }
          sel.append(opt);
        } else {
          sel.disabled = true;
          sel.append(
            new Option(
              managed
                ? `No Forge scripts folder linked${managedHint ? ` (${managedHint})` : ''}. Configure it in The Forge Storage.`
                : 'No existing scripts yet — map folder and save new ones here',
              '',
              true,
              false,
            ),
          );
        }
        hudLog('folder:cleared', {});
        try { window.dispatchEvent(new CustomEvent('tp:folderScripts:populated', { detail: { count: 0 } })); } catch {}
        try { announceCount(0); } catch {}
        return;
      }
      const fallbackFingerprint = fingerprintNames(filtered.map((f) => ({ name: f.name })));
      const prevFallback = lastFallbackFingerprints.get(sel);
      if (fallbackFingerprint && fallbackFingerprint === prevFallback) {
        if (shouldTraceMappedFolder()) {
          debugLog('[MAPPED-FOLDER] populateSelectFromFiles skipped duplicate', { fingerprint: fallbackFingerprint, count: filtered.length });
        }
        return;
      }
      if (fallbackFingerprint) {
        lastFallbackFingerprints.set(sel, fallbackFingerprint);
      }
      sel.disabled = false;
      for (const f of filtered) {
        const opt = new Option(f.name, f.name) as HTMLOptionElement & {
          __fileHandle?: FileSystemFileHandle;
          __file?: File;
          _handle?: FileSystemFileHandle;
          _file?: File;
        };
        try { opt._file = f; } catch {}
        try { opt.__file = f; } catch {}
        try { mappedEntries.push({ id: f.name, title: f.name, handle: f as any }); } catch {}
        if (shouldTraceMappedFolder()) {
          try {
            debugLog('[MAPPED-FOLDER] option created', {
              id: f.name,
              label: f.name,
              hasHandle: false,
              hasFile: true,
            });
          } catch {}
        }
        sel.append(opt);
      }
      if (shouldTraceMappedFolder()) {
        debugLog('[MAPPED-FOLDER] syncing mapped entries (fallback)', { count: mappedEntries.length });
      }
      try { ScriptStore.syncMapped(mappedEntries); } catch {}
      try { window.dispatchEvent(new CustomEvent('tp:scripts-updated')); } catch {}
      hudLog('folder:mapped', { count: filtered.length });
      // Preselect last used script if present (fallback path) + maybe auto-load
      try {
        const restoreId = consumeLastScriptId(mappedEntries);
        if (restoreId) {
          setSelectedById(sel, restoreId);
          syncSidebarSelection(restoreId);
          restoredLastScript = true;
          hudLog('script:last:preselect', { id: restoreId });
          void loadScriptById(restoreId);
          maybeAutoLoad(sel);
        } else if (!restoreStillPossible()) {
          const last = getLastScriptName();
          if (last) {
            setSelectedByName(sel, last);
            hudLog('script:last:preselect', { name: last });
          }
          maybeAutoLoad(sel);
        }
      } catch {}
      const cnt = sel.options.length;
      try { window.dispatchEvent(new CustomEvent('tp:folderScripts:populated', { detail: { count: cnt } })); } catch {}
      try { announceCount(cnt); } catch {}
      try { sel.setAttribute('aria-busy','false'); } catch {}
      queueMicrotask(() => {
        try { if (sidebar) sidebar.value = sel.value; } catch {}
      });
    } catch {}
  }
  function announceCount(n: number) {
    try {
      // Ensure a small aria-live polite status next to the select
      const id = (sel && sel.id) ? ('scriptsStatus_' + sel.id) : 'scriptsStatus_generic';
      let s = document.getElementById(id) as HTMLElement | null;
      if (!s) {
        s = document.createElement('span');
        s.id = id;
        s.setAttribute('aria-live', 'polite');
        s.className = 'chip sidebar-hint';
        // Try to place after the select; fallback to append to its parent
        if (sel && sel.parentElement) {
          sel.parentElement.appendChild(s);
        } else {
          document.body.appendChild(s);
        }
      }
      s.textContent = n === 0
        ? (
          isMappedFolderManagedByNursery()
            ? 'No Forge scripts folder linked — configure in The Forge Storage.'
            : 'No existing scripts yet — map folder and save new ones here'
        )
        : (n === 1 ? '1 script found' : `${n} scripts found`);
    } catch {}
  }
}

async function readHandleOrFile(handleOrFile: any): Promise<{ name: string; text: string }> {
  try {
    const file: File = handleOrFile?.getFile ? await handleOrFile.getFile() : handleOrFile;
    const name = file?.name || 'Untitled';
    if (file && /\.docx$/i.test(name)) {
      const text = await docxToTextViaMammoth(file);
      return { name, text };
    }
    const text = file ? await file.text() : '';
    return { name, text };
  } catch (e) {
    const name = 'Untitled';
    return { name, text: '[error] Failed to read file: ' + (e && (e as any).message || String(e)) + '[/error]' };
  }
}

async function docxToTextViaMammoth(file: File): Promise<string> {
  try {
    const ensure = (window as any).ensureMammoth as undefined | (() => Promise<any>);
    const mod = ensure ? await ensure() : null;
    const mammoth = (mod && (mod.mammoth || mod.default)) || (window as any).mammoth || null;
    if (!mammoth) throw new Error('mammoth not available');
    const buf = await file.arrayBuffer();
  const res = await mammoth.extractRawText({ arrayBuffer: buf });
    const raw = (res && (res.value || res.text || '')) || '';
    return String(raw).replace(/\r\n/g, '\n').replace(/\n{3,}/g, '\n\n').trim();
  } catch (e) {
    try { console.warn('[mapped-folder] mammoth parse failed', e); } catch {}
    return '';
  }
}

let _lastCount = 0; // track last script count for HUD logging

export async function recheckMappedFolderPermissions() {
  try {
    if (isMappedFolderManagedByNursery()) {
      toast(`Scripts folder is managed by The Forge. Configure it in The Forge > Settings > Storage (${getNurseryStorageSettingsUrl()}).`);
      return false;
    }
    const dir = (window as any).__tpFolder?.get?.();
    if (!dir) { toast('No folder mapped'); return false; }
    // @ts-ignore
    const res = await (dir as any).requestPermission?.({ mode: 'read' });
    const granted = res === 'granted';
    hudLog('folder:permission', { granted });
    toast(granted ? 'Folder access granted' : 'Folder access denied');
    if (!granted) {
      try { await (window as any).__tpFolder?.clear?.(); } catch {}
    }
    return granted;
  } catch { return false; }
}

// tiny toast: HUD event first; alert fallback to ensure visibility
function toast(msg: string) {
  hudLog('toast', { msg });
  try { window.dispatchEvent(new CustomEvent('tp:toast', { detail: { msg, ts: Date.now() } })); } catch {}
  try { if (!(window as any).HUD) alert(msg); } catch {}
}

// Optional binder for a recheck button; no-op if selector missing
export function bindPermissionButton(selector: string) {
  try {
    const btn = document.querySelector(selector) as HTMLButtonElement | null;
    if (!btn) return;
    btn.addEventListener('click', () => { try { recheckMappedFolderPermissions(); } catch {} });
  } catch {}
}

// "Last script" helpers
function getLastScriptName(): string | null {
  try { return localStorage.getItem('tp_last_script_name'); } catch { return null; }
}
function setSelectedByName(sel: HTMLSelectElement, name: string | null): void {
  if (!name) return;
  for (let i = 0; i < sel.options.length; i++) {
    if (sel.options[i].text === name) { sel.selectedIndex = i; break; }
  }
}
function setSelectedById(sel: HTMLSelectElement | null, id: string | null): void {
  if (!sel || !id) return;
  for (let i = 0; i < sel.options.length; i++) {
    if (sel.options[i].value === id) {
      sel.selectedIndex = i;
      return;
    }
  }
}
function syncSidebarSelection(id: string | null): void {
  if (!id) return;
  const sidebar = document.getElementById('scriptSelectSidebar') as HTMLSelectElement | null;
  if (sidebar) {
    setSelectedById(sidebar, id);
  }
}
function maybeAutoLoad(sel: HTMLSelectElement) {
  try {
    if (restoredLastScript) {
      return;
    }
    const s = (window as any).__tpSettings?.get?.() || (window as any).__tpSettingsStore || null;
    const auto = !!(s && s.autoLoadLastScript);
    if (auto && sel.selectedIndex >= 0) {
      sel.dispatchEvent(new Event('change', { bubbles: true }));
      hudLog('script:auto-load:last', { name: sel.options[sel.selectedIndex]?.text });
    }
  } catch {}
}
